const filas=$input.all().map(item=>item.json);
if(!filas.length)throw new Error('La consulta no devolvio filas para el piloto.');
const porSerie=new Map();
for(const fila of filas)porSerie.set(`${fila.id_sucursal}|${fila.id_articulo}`,fila);
const series=[...porSerie.values()];
const contar=(campo)=>series.reduce((acc,fila)=>{const valor=String(fila[campo]||'sin_clasificar');acc[valor]=(acc[valor]||0)+1;return acc;},{});
const sucursales=new Set(filas.map(r=>String(r.id_sucursal)));
const rubros=new Set(filas.map(r=>String(r.rubro||'sin_clasificar').trim()));
const subrubros=new Set(filas.map(r=>String(r.subrubro||'sin_clasificar').trim()));
const gruposArticulo=new Set(filas.map(r=>String(r.grupo_articulo||'sin_clasificar').trim()));
const colores=new Set(filas.map(r=>String(r.color||'sin_clasificar').trim()));
const talles=new Set(filas.map(r=>String(r.talle||'sin_clasificar').trim()));
const fechas=filas.map(r=>String(r.fecha_comprobante)).sort();
return [{json:{
  estado:'DATASET_PILOTO_OK',
  solo_lectura:true,
  criterio_muestra:'base madura por sucursal y patron, mas cohortes de historia, inactividad y segunda seleccion',
  filas_semanales:filas.length,
  series_articulo_sucursal:series.length,
  sucursales:sucursales.size,
  rubros:rubros.size,
  subrubros:subrubros.size,
  grupos_articulo:gruposArticulo.size,
  colores:colores.size,
  talles:talles.size,
  cohortes_historia:contar('cohorte_historia'),
  estados_actividad:contar('estado_actividad'),
  series_segunda_seleccion:series.filter(r=>r.es_segunda_seleccion===true).length,
  series_regulares:series.filter(r=>r.patron_muestra==='regular').length,
  series_intermitentes:series.filter(r=>r.patron_muestra==='intermitente').length,
  fecha_minima:fechas[0],
  fecha_maxima:fechas[fechas.length-1],
  nodo_datos:'Postgres - Ventas semanales piloto',
  siguiente_paso:'Procesar la salida con el motor Python y revisar las cohortes no maduras antes de reposicion.'
}}];
